<?php
function svCatalogHidden(int $surveyId,string $action):void {
 echo '<input type="hidden" name="csrf" value="'.h(csrf()).'"><input type="hidden" name="id" value="'.$surveyId.'"><input type="hidden" name="action" value="'.h($action).'"><input type="hidden" name="request_id" value="'.bin2hex(random_bytes(16)).'">';
}
function svCatalogCartCard(array $item,int $surveyId,bool $locked,string $selected=''):void {
 $rooms=svCatalogRooms();$roomKey=svCatalogRoomKey((string)$item['room']);$qty=(int)$item['quantity'];
 ?><article class="svc-cart-card" data-item-id="<?=(int)$item['id']?>" data-room-key="<?=h($roomKey)?>" <?=$selected!==''&&$selected!==$roomKey?'hidden':''?>><div class="svc-cart-name"><span class="svc-cart-emoji" aria-hidden="true"><?=h($rooms[$roomKey][1])?></span><div><strong data-cart-name><?=h($item['item_name'])?></strong><small data-cart-room><?=h($item['room'])?></small></div><b data-cart-volume><?=number_format($qty*(float)$item['unit_volume'],2,',','.')?> m³</b></div>
 <div class="svc-cart-controls"><small data-cart-unit><?=number_format((float)$item['unit_volume'],2,',','.')?> m³ / adet</small><form method="post" data-catalog-step><?php svCatalogHidden($surveyId,'catalog_step');?><input type="hidden" name="item_id" value="<?=(int)$item['id']?>"><input type="hidden" name="confirm_remove" value="1"><button type="submit" name="delta" value="-1" class="svc-step" aria-label="<?=h($item['item_name'])?> adedini azalt" <?=$locked?'disabled':''?>>−</button><output data-cart-quantity><?=$qty?></output><button type="submit" name="delta" value="1" class="svc-step" aria-label="<?=h($item['item_name'])?> adedini artır" <?=$locked?'disabled':''?>>＋</button></form></div>
 <?php if(!$locked):?><details class="svc-edit"><summary>Hacim / eşya bilgilerini düzenle</summary><form method="post" class="sv-edit-form"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="id" value="<?=$surveyId?>"><input type="hidden" name="action" value="update_item"><input type="hidden" name="item_id" value="<?=(int)$item['id']?>"><label>Oda<input name="room" value="<?=h($item['room'])?>" maxlength="100" required></label><label>Eşya<input name="item_name" value="<?=h($item['item_name'])?>" maxlength="190" required></label><label>Adet<input type="number" name="quantity" min="1" max="500" value="<?=$qty?>" required></label><label>Birim hacim · m³<input data-ek-volume type="number" name="unit_volume" min="0" max="100" step="0.001" value="<?=h($item['unit_volume'])?>" required></label><button class="sv-btn" type="submit">Bilgileri kaydet</button></form></details><?php endif;?>
 <p class="svc-cart-note" data-cart-note <?=empty($item['notes'])?'hidden':''?>><?=h($item['notes']??'')?></p></article><?php
}
function svCatalogView(int $surveyId,array $items,bool $locked,string $selected):void {
 $rooms=svCatalogRooms();if(!isset($rooms[$selected]))$selected='living';$snapshot=svCatalogSnapshot(db(),$surveyId);$catalog=svCatalogItems();
 ?><?=str_replace('<svg xmlns=', '<svg class="svc-art-defs" aria-hidden="true" width="0" height="0" xmlns=', (string)file_get_contents(__DIR__.'/../assets/survey-items.svg'))?><section class="sv-card svc-workspace" id="sv-inventory" data-locked="<?=$locked?'1':'0'?>"><div class="sv-section-title"><div><small>GÖRSEL EŞYA SEÇİMİ</small><h2><?=$locked?'Oda oda envanter':'Odayı seç, eşyaya dokun'?></h2><p><?=$locked?'Onaylı dosya salt okunur. Değişiklik için kontrol sekmesinden revizyon açın.':'Her dokunuş 1 adet ekler. Hacimler tahminidir; gerektiğinde düzeltin.'?></p></div><span class="sv-pill">Ev taşıma envanteri</span></div>
 <nav class="svc-room-tabs" aria-label="Evdeki odalar"><?php foreach($rooms as $key=>$room):?><a href="ekspertiz.php?id=<?=$surveyId?>&amp;room=<?=$key?>#sv-inventory" data-room-tab="<?=$key?>" class="<?=$selected===$key?'is-active':''?>"><span aria-hidden="true"><?=$room[1]?></span><span><?=$room[0]?></span><b data-room-count><?=$snapshot['rooms'][$key]['pieces']??0?></b></a><?php endforeach;?></nav>
 <div class="svc-room-toolbar"><div><h3 id="svc-room-title"><?=h($rooms[$selected][0])?></h3><span id="svc-room-total"><?=number_format($snapshot['rooms'][$selected]['volume']??0,2,',','.')?> m³</span></div><label class="svc-search-label">Eşya ara<input type="search" id="svc-search" placeholder="Bu odada eşya bul…" autocomplete="off"></label></div>
 <div class="svc-layout"><div class="svc-picker"><p class="svc-estimate">Katalog hacimleri yaklaşık değerlerdir. Eşyanın ölçüsü ve paketlenme şekli hacmi değiştirebilir.</p>
 <?php foreach($rooms as $key=>$room):?><div class="svc-item-grid" data-room-grid="<?=$key?>" <?=$selected!==$key?'hidden':''?>><?php foreach($catalog as $itemKey=>$entry):if(!in_array($key,$entry[4],true))continue;?><form method="post" data-catalog-add data-search="<?=h($entry[0])?>"><?php svCatalogHidden($surveyId,'catalog_add');?><input type="hidden" name="room_key" value="<?=$key?>"><input type="hidden" name="catalog_key" value="<?=$itemKey?>"><button class="svc-item-card" type="submit" <?=$locked?'disabled':''?> aria-label="<?=h($room[0].' · '.$entry[0].' ekle')?>"><span class="svc-item-emoji" aria-hidden="true"><?=$entry[2]?></span><svg class="svc-item-art" aria-hidden="true" viewBox="0 0 160 110"><use href="#svc-<?=$entry[3]?>"></use></svg><strong><?=$entry[0]?></strong><small><?=number_format($entry[1],2,',','.')?> m³ / adet</small><span class="svc-add-label" aria-hidden="true"><?=$locked?'Salt okunur':'＋ Ekle'?></span></button></form><?php endforeach;?></div><?php endforeach;?>
 <p id="svc-search-empty" class="svc-empty" hidden>Bu odada eşleşen eşya bulunamadı. Özel eşya alanından ekleyebilirsiniz.</p></div>
 <section class="svc-cart" aria-label="Odanın eşya listesi"><div class="svc-cart-heading"><h3>Bu odadaki eşyalar</h3><span id="svc-room-pieces"><?=$snapshot['rooms'][$selected]['pieces']??0?> adet</span></div><div id="svc-cart-items"><?php foreach($items as $item):svCatalogCartCard($item,$surveyId,$locked,$selected);endforeach;?></div><p id="svc-cart-empty" class="svc-empty">Henüz eşya yok. Soldaki kartlardan seçin.</p></section></div>
 <div class="svc-summary" aria-live="polite"><span>🏠 Tüm ev <b id="svc-total-volume"><?=number_format($snapshot['volume'],2,',','.')?> m³</b></span><span id="svc-total-pieces"><?=$snapshot['pieces']?> adet</span><span id="svc-save-state">Kayıtlı envanter</span><?php if(!$locked):?><form method="post" data-catalog-clear><?php svCatalogHidden($surveyId,'catalog_clear');?><input type="hidden" name="revision" value="<?=h($snapshot['revision'])?>"><input type="hidden" name="confirm_clear" value="0"><button type="submit" class="svc-clear" <?=$snapshot['pieces']===0?'disabled':''?>>Envanteri temizle</button></form><?php endif;?></div><p id="svc-message" role="status" aria-live="polite"></p><a id="svc-reload" class="svc-reload" href="ekspertiz.php?id=<?=$surveyId?>#sv-inventory" hidden>Güncel listeyi yenile →</a>
 <script type="application/json" id="svc-state"><?=json_encode(['survey_id'=>$surveyId,'actor_id'=>(int)$_SESSION['uid'],'locked'=>$locked,'csrf'=>csrf(),'selected'=>$selected,'rooms'=>$rooms,'snapshot'=>$snapshot],JSON_UNESCAPED_UNICODE|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_THROW_ON_ERROR)?></script>
 <template id="svc-cart-template"><?php svCatalogCartCard(['id'=>0,'room'=>'Salon','item_name'=>'','quantity'=>1,'unit_volume'=>0,'notes'=>''],$surveyId,$locked);?></template></section><?php
}
